"""The endpoint the payment provider calls when a payment settles."""
from callback import log, mq
from callback.orders import mark_paid
from callback.pool import PoolTimeout
from callback.signature import verify


def handle_callback(request):
    """Marks the order paid and announces it; a callback the pool cannot serve in time is answered 503, for a retry."""
    payload = verify(request)
    if payload.status != "paid":
        return {"ignored": payload.status}
    try:
        mark_paid(payload.order_id, payload.amount)
    except PoolTimeout as error:
        log.error(str(error), exc_info=True)
        return {"retry": True}, 503
    mq.publish("payment.completed", {"order_id": payload.order_id})
    return {"ok": True}

"""A fixed pool of database connections that the callback workers share."""
import queue

from callback import db, metrics
from callback.settings import POOL_SIZE, TIMEOUT_MS


class PoolTimeout(Exception):
    """No connection came free within the configured timeout."""


_idle = queue.Queue(maxsize=POOL_SIZE)
for _ in range(POOL_SIZE):
    _idle.put(db.connect())


def in_use():
    """How many of the pool's connections are lent out."""
    return POOL_SIZE - _idle.qsize()


class _Lease:
    """A connection lent from the pool, returned when the block that holds it ends."""

    def __init__(self, connection):
        self.connection = connection

    def __enter__(self):
        return self.connection

    def __exit__(self, *exc_info):
        _idle.put(self.connection)


def acquire():
    """Lends a connection, waiting at most the configured timeout for one to come free."""
    metrics.gauge("pool_in_use", in_use())
    try:
        connection = _idle.get(timeout=TIMEOUT_MS / 1000)
    except queue.Empty:
        metrics.increment("pool_timeouts")
        raise PoolTimeout(f"acquire connection timeout after {TIMEOUT_MS}ms (pool_size={POOL_SIZE}, in_use={in_use()})") from None
    return _Lease(connection)

"""Forwards the gateway's requests to the services behind it."""
import httpx

from gateway import log, routes

UPSTREAM_TIMEOUT_S = 5.0

client = httpx.AsyncClient()


async def forward(request):
    """Sends a request on to its upstream; an upstream that does not answer in time is answered 504."""
    upstream = routes.upstream_of(request.url.path)
    try:
        return await client.send(request.with_host(upstream), timeout=UPSTREAM_TIMEOUT_S)
    except httpx.TimeoutException:
        log.error(f"upstream {upstream} timed out after {UPSTREAM_TIMEOUT_S * 1000:.0f}ms: {request.method} {request.url.path} 504")
        return routes.gateway_timeout(upstream)
